// Todo App JavaScript Logic
const form = document.querySelector("#todo-form");
const input = document.querySelector("#todo-input");
const list = document.querySelector("#todo-list");

// Load saved tasks from localStorage or start empty
let tasks = JSON.parse(localStorage.getItem("tasks")) || [];

function saveAndRender() {
  localStorage.setItem("tasks", JSON.stringify(tasks));
  list.innerHTML = "";

  tasks.forEach((task, index) => {
    const li = document.createElement("li");
    li.className = task.completed ? "completed" : "";
    li.innerHTML = `
      <span class="task-text">${task.text}</span>
      <button class="delete-btn" data-index="${index}">Delete</button>
    `;
    list.appendChild(li);
  });
}

// Add new task
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const text = input.value.trim();
  if (!text) return;
  tasks.push({ text, completed: false });
  input.value = "";
  saveAndRender();
});

// Toggle complete or delete (Event Delegation)
list.addEventListener("click", (e) => {
  const index = e.target.dataset.index;
  if (e.target.classList.contains("delete-btn")) {
    tasks.splice(index, 1); // Delete item
    saveAndRender();
  } else if (e.target.classList.contains("task-text")) {
    const parentIndex = Array.from(list.children).indexOf(e.target.parentElement);
    tasks[parentIndex].completed = !tasks[parentIndex].completed;
    saveAndRender();
  }
});

// Initial render on page load
saveAndRender();

Welcome to **Python Programming for Beginners**!

Created by Dutch programmer Guido van Rossum and released in 1991, **Python** was built with one primary philosophy: **code should look like plain English**.

In many programming languages, printing a simple message requires 5 to 10 lines of complex boilerplate:

```c
// In C++, printing "Hello" requires all of this:
#include <iostream>
int main() {
    std::cout << "Hello, World!" << std::endl;
    return 0;
}
```

In Python, the exact same task is **one single readable line**:

```python
# In Python:
print("Hello, World!")
```

Because Python is so readable, you spend your time solving actual problems instead of fighting syntax punctuation!

Python provides the elegant **`@property`** decorator to create getters and setters with clean attribute syntax:

```python
class BankAccount:
    def __init__(self, owner: str, balance: float):
        self.owner = owner
        self._balance = balance # Leading underscore signals internal attribute!

    # 1. Getter property: accessed as account.balance (no parentheses!)
    @property
    def balance(self) -> float:
        return self._balance

    # 2. Setter property: controls updates with validation!
    @balance.setter
    def balance(self, new_balance: float):
        if new_balance < 0:
            raise ValueError("Balance cannot be set to a negative number!")
        self._balance = new_balance

acc = BankAccount("Ada", 1000)
print(acc.balance) # 1000 (Calls the getter!)

acc.balance = 1500 # Calls the setter validation!
# acc.balance = -500 # RAISES ValueError: Balance cannot be set to a negative number!
```

You get full validation safety with the clean syntax of normal variables!

You can trigger your own exceptions when business rules are violated:

```python
def withdraw_funds(balance: float, amount: float) -> float:
    if amount <= 0:
        raise ValueError("Withdrawal amount must be greater than zero.")
    if amount > balance:
        raise ValueError(f"Insufficient funds! Balance is ₦{balance:,.2f}.")

    return balance - amount

try:
    new_bal = withdraw_funds(50000, 75000)
except ValueError as err:
    print(f"Transaction Rejected: {err}")
```

Using `raise` keeps your business logic strict and prevents invalid states.
